<x-capstone::card x-show="showDocuments"><div class="px-6 flex flex-col md:flex-row md:items-center justify-between gap-4"><div><h2 class="text-lg font-semibold flex items-center gap-2"><x-capstone::icon name="FileText" class="w-5 h-5" />Required Documents</h2><p class="text-sm text-muted-foreground">Upload all required documents to proceed to sidang TA</p></div><div class="text-right"><p class="text-sm font-medium" x-text="approvedCount+' / '+requirements.length+' Approved'"></p><div class="w-32 h-2 bg-muted rounded-full mt-1 overflow-hidden"><div class="h-full bg-success transition-all duration-500" :style="{width:(requirements.length?approvedCount/requirements.length*100:0)+'%'}"></div></div></div></div>
    <div class="px-6"><div x-show="!data.document_requirements.length" class="bg-yellow-50 border border-yellow-200 rounded-lg p-4 flex gap-3"><x-capstone::icon name="CircleAlert" class="h-4 w-4 text-yellow-600 shrink-0" /><div><h3 class="font-medium">No Document Requirements</h3><p class="text-sm">No TA document requirements have been configured for this period. Please contact your administrator.</p></div></div>
        <div class="space-y-3"><template x-for="req in requirements" :key="req.id"><div class="flex flex-wrap sm:flex-nowrap items-center justify-between gap-3 p-4 border rounded-lg transition-all" :class="documentStatus(req.name)==='APPROVED'?'bg-green-50 border-green-200':documentStatus(req.name)==='REJECTED'?'bg-red-50 border-red-200':documentStatus(req.name)==='PENDING'?'bg-yellow-50 border-yellow-200':'bg-gray-50 border-gray-200'"><div class="flex items-start gap-3 flex-1 min-w-0"><div class="mt-0.5 shrink-0">@foreach(['APPROVED'=>['CircleCheck','text-green-600'],'REJECTED'=>['CircleAlert','text-red-600'],'PENDING'=>['Clock','text-yellow-600']] as $status=>[$icon,$color])<x-capstone::icon :name="$icon" class="w-5 h-5 {{ $color }}" x-show="documentStatus(req.name)==='{{ $status }}'" />@endforeach<x-capstone::icon name="FileText" class="w-5 h-5 text-gray-400" x-show="!documentStatus(req.name)" /></div><div class="flex-1 min-w-0"><div class="flex flex-wrap items-center gap-2"><p class="font-medium" x-text="req.name"></p>@foreach(['APPROVED'=>['Approved','green'],'REJECTED'=>['Rejected','red'],'PENDING'=>['Pending Review','yellow']] as $status=>[$label,$color])<span x-show="documentStatus(req.name)==='{{ $status }}'" class="rounded-md px-2 py-0.5 bg-{{ $color }}-100 text-{{ $color }}-800 text-xs">{{ $label }}</span>@endforeach</div><p x-show="req.description" class="text-sm text-muted-foreground" x-text="req.description"></p><div x-show="documentStatus(req.name)==='REJECTED' && documentFor(req.name)?.feedback" class="mt-2 text-sm text-red-700 bg-red-100 p-2 rounded"><span class="font-semibold">Feedback:</span> <span x-text="documentFor(req.name)?.feedback"></span></div></div></div><x-capstone::button x-show="documentStatus(req.name)!=='APPROVED'" size="sm" ::disabled="!data.can_upload" @click="openUpload(req.name)"><x-capstone::icon name="Upload" class="h-4 w-4 mr-2" /><span x-text="documentFor(req.name)?'Re-upload':'Upload'"></span></x-capstone::button></div></template></div>
    </div>
</x-capstone::card>
